-- 前提：tags存在，event_tags不存在
RENAME TABLE tags TO event_tags;
SELECT id, name FROM event_tags;

CREATE TABLE visits (
 id INT PRIMARY KEY,
 visit_day DATE NOT NULL,
 arrived_at DATETIME NULL
);
-- 合法日期示意：2027-05-06；不是每个形似YYYY-MM-DD的串都有效。

CREATE TABLE default_demo (id INT PRIMARY KEY, score INT DEFAULT 0);
INSERT INTO default_demo (id) VALUES (1);
INSERT INTO default_demo (id, score) VALUES (2, NULL);

CREATE TABLE tickets (id INT PRIMARY KEY, title VARCHAR(30));
公开SQL字段：id，例如101。
内部回放身份：由平台管理，不是额外可查询列。

CREATE TABLE teams (id INT PRIMARY KEY);
CREATE TABLE members (
 id INT PRIMARY KEY, team_id INT,
 FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE RESTRICT
);

CREATE TABLE categories (id INT PRIMARY KEY, title VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE items (
 id INT PRIMARY KEY, name VARCHAR(60) NOT NULL,
 category_id INT, status INT DEFAULT 0,
 FOREIGN KEY (category_id) REFERENCES categories(id)
) ENGINE=InnoDB;
